import{_ as t,a as r,b as a,c as o,d as i,e as s,f as n,g as l}from"./chunks/M-SS-BTLBd.4ze8KdSv.js";import{_ as u}from"./chunks/M-SS.C4V7iNpZ.js";import{_ as c,o as p,c as d,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Transmetteur Libre","description":"","frontmatter":{"source_hash":"51a5c41463","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/troubleshoot/librebridge.md","filePath":"fr/troubleshoot/librebridge.md"}'),h={name:"fr/troubleshoot/librebridge.md"};function v(b,e,f,g,z,q){return p(),d("div",null,[...e[0]||(e[0]=[m('<p>De nombreux transmetteurs Libre commerciaux sont disponibles sur le marché ; par ordre de sortie, on trouve Blucon, MiaoMiao et Droplet, pour ne citer que les plus connus. Ils reposent tous sur le concept LimiTTer et l&#39;implémentation blueReader : une puce de lecture NFC CR95LF et un microcontrôleur BLE Nordic Semiconductor. La première lit le capteur et le second envoie les données en Bluetooth à votre téléphone (ou à votre montre Wear) toutes les 5 minutes.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p><strong>Tant que votre transmetteur arrive à lire le capteur et à transmettre les données, vous pouvez considérer qu&#39;il fonctionne correctement.</strong></p></div><p>Lorsque xDrip affiche des valeurs manquantes, vous devez comprendre ce qui ne va pas. Ce n&#39;est pas toujours facile.</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>Commencez par les choses simples : redémarrez d&#39;abord votre téléphone.</p></div><p>Puisque vous êtes ici, vérifiez vos <a href="./../install/libreBT.html#bridge-settings">paramètres Bluetooth de xDrip</a> et n&#39;hésitez pas à en désactiver certains.</p><p>Allez ensuite dans État du système, puis dans BT Device. Si vous ne savez pas comment faire, consultez d&#39;abord <a href="./systemstatus.html">cette page</a>.</p><h3 id="classis-status-page" tabindex="-1">Page d&#39;état classique <a class="header-anchor" href="#classis-status-page" aria-label="Permalink to &quot;Page d&#39;état classique {#classis-status-page}&quot;">​</a></h3><p><strong>Si votre transmetteur apparaît comme LimiTTer, cela signifie probablement qu&#39;il n&#39;est pas connecté ou pas reconnu.</strong></p><p>Tous les appareils apparaissent comme LimiTTer tant qu&#39;ils ne sont pas connectés ; seuls la connexion directe Libre 2 et quelques autres transmetteurs (le BluCon par exemple) restent indiqués comme LimiTTer (et évidemment <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a> lui-même).</p><img src="'+t+'" style="zoom:75%;"><p>Vérifiez la version de xDrip et assurez-vous qu&#39;elle est assez récente pour prendre en charge le transmetteur auquel vous vous connectez.</p><p>xDrip a connu trop de versions et d&#39;améliorations pour donner un tableau précis des versions minimales requises.<br> Utilisez au moins la <a href="./../install/download.html#latest-release">dernière version publiée</a> de xDrip et, si vous pensez que votre transmetteur nécessite des fonctions plus récentes, essayez de passer à la dernière <a href="./../install/download.html#pre-release">pré-version</a>.</p><p>Ne désinstallez pas xDrip pour changer de version. Vous pouvez facilement <a href="./../use/update.html">passer d&#39;une version à l&#39;autre</a> sans perdre vos données ni vos paramètres.</p><h3 id="bt-device-page" tabindex="-1">Page BT Device <a class="header-anchor" href="#bt-device-page" aria-label="Permalink to &quot;Page BT Device {#bt-device-page}&quot;">​</a></h3><p>Faites glisser l&#39;écran vers la gauche pour afficher la page BT Device.</p><img src="'+u+'" style="zoom:75%;"><img src="'+r+'" style="zoom:75%;"><h4 id="bluetooth-pairing" tabindex="-1">Bluetooth Pairing <a class="header-anchor" href="#bluetooth-pairing" aria-label="Permalink to &quot;Bluetooth Pairing {#bluetooth-pairing}&quot;">​</a></h4><p>Si vous êtes déjà passé par ici : <strong>Bluetooth Pairing doit être désactivé. Si vous l&#39;avez modifié par erreur, appuyez sur la ligne pour revenir à cet état :</strong></p><img src="'+a+'" style="zoom:75%;"><h4 id="bluetooth-device" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device" aria-label="Permalink to &quot;Bluetooth Device {#bluetooth-device}&quot;">​</a></h4><p>Le Bluetooth doit toujours être connecté.</p><img src="'+o+'" style="zoom:75%;"><p>Premières actions à effectuer si le Bluetooth n&#39;est pas connecté :</p><ol><li>Vérifiez vos <a href="./../install/libreBT.html#bridge-settings">paramètres Bluetooth</a> et utilisez Redémarrer le collecteur dans l&#39;onglet classique de l&#39;État du système. Si le redémarrage du collecteur vous a permis de retrouver la connexion, le problème vient peut-être de vos paramètres Bluetooth ou des paramètres d&#39;économie d&#39;énergie du téléphone.</li><li>Ouvrez Paramètres Android -&gt; Applications -&gt; xDrip : vérifiez qu&#39;il peut s&#39;exécuter en arrière-plan et qu&#39;il n&#39;est pas optimisé pour économiser la batterie.</li><li>Toujours dans Applications, cherchez les applications système Bluetooth (elles peuvent être masquées par défaut et accessibles depuis le menu à trois points, en haut à droite) : vérifiez que tous les services Bluetooth peuvent s&#39;exécuter en arrière-plan et ne sont pas optimisés.</li></ol><p>Si le transmetteur n&#39;est toujours pas visible, essayez un <a href="./../install/libreBT.html#connect-bluetooth-bridge">Scan Bluetooth</a> pour le trouver.</p><ul><li>Si le scan Bluetooth ne le trouve pas, continuez <a href="#bluetooth-scan-doesnt-find-the-bridge">ici</a>.</li><li>Si le scan Bluetooth vous permet de le sélectionner mais qu&#39;il ne reste pas connecté, continuez <a href="#bridge-doesnt-stay-connected">ici</a>.</li></ul><h4 id="phone-service-state" tabindex="-1">Phone Service State <a class="header-anchor" href="#phone-service-state" aria-label="Permalink to &quot;Phone Service State {#phone-service-state}&quot;">​</a></h4><p>Phone Service State indique la dernière fois que des données ont été reçues du transmetteur ; cela doit remonter à moins de 5 minutes.<br> Next Wake up décompte le temps jusqu&#39;aux prochaines données attendues, puis repart de 5 minutes.</p><img src="'+i+'" style="zoom:75%;"><p>Si vous avez configuré une montre Android Wear comme collecteur, consultez la page <a href="./../smartwatch/wear.html#standalone-collector-mode">mode collecteur autonome</a>. Si vous n&#39;avez pas de montre Android Wear avec xDrip correctement installé, <a href="./../smartwatch/wear.html">désactivez le collecteur Wear</a>.</p><img src="'+s+'" style="zoom:75%;"><p>N&#39;essayez pas de connecter votre transmetteur à une montre connectée tant que le fonctionnement avec votre téléphone n&#39;est pas fiable (aucune perte de connexion).</p><h4 id="bridge-information" tabindex="-1">Informations sur le transmetteur <a class="header-anchor" href="#bridge-information" aria-label="Permalink to &quot;Informations sur le transmetteur {#bridge-information}&quot;">​</a></h4><p>Vous verrez aussi diverses informations sur le transmetteur, comme l&#39;adresse Mac et les versions matérielle et firmware. Notez que le niveau de batterie n&#39;est pas disponible sur les transmetteurs Blucon : 100 % signifie seulement qu&#39;il est encore utilisable.</p><img src="'+n+'" style="zoom:75%;"><p>Il est fortement recommandé de <a href="./bridgeFW.html">mettre à jour</a> le firmware de votre appareil vers la dernière version disponible.</p><h4 id="no-sensor-found" tabindex="-1">No Sensor Found <a class="header-anchor" href="#no-sensor-found" aria-label="Permalink to &quot;No Sensor Found {#no-sensor-found}&quot;">​</a></h4><p>Les erreurs No sensor found sont généralement dues à un mauvais positionnement du transmetteur sur le capteur. Certains transmetteurs n&#39;ont aucune tolérance quant à la distance et à l&#39;angle par rapport à la zone d&#39;antenne du capteur. Cela peut aussi venir d&#39;un problème interne au transmetteur, d&#39;un problème de firmware...<br> Comme ce message reste affiché, vérifiez que l&#39;heure indiquée est récente. S&#39;il indique en permanence il y a 5 minutes, le capteur n&#39;est pas détecté. Si c&#39;est arrivé il y a quelques heures, ignorez-le simplement.</p><img src="'+l+'" style="zoom:75%;"><p>Si vous utilisez un transmetteur peu sensible au positionnement, il présente peut-être une panne interne ou un firmware corrompu.</p><ul><li>Réinitialisez-le d&#39;abord et chargez-le complètement.</li><li>Essayez de recharger ou de <a href="./bridgeFW.html">mettre à jour</a> son firmware.</li></ul><p>Si vous utilisez un capteur autre qu&#39;un Libre 1, vous devrez peut-être ajouter un algorithme OOP (Out Of Process).</p><p>Utilisez <a href="./systemstatus.html#restart-collector-forget-device">Oublier ce périphérique</a> dans xDrip et installez l&#39;application du fabricant pour écarter une panne de l&#39;appareil. Contactez le fabricant pour obtenir de l&#39;aide.</p><h3 id="bluetooth-scan-doesnt-find-the-bridge" tabindex="-1">Le scan Bluetooth ne trouve pas le transmetteur <a class="header-anchor" href="#bluetooth-scan-doesnt-find-the-bridge" aria-label="Permalink to &quot;Le scan Bluetooth ne trouve pas le transmetteur {#bluetooth-scan-doesnt-find-the-bridge}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>C&#39;est tout à fait normal lorsque votre transmetteur est connecté à xDrip.</p></div><ol><li>Vérifiez qu&#39;il n&#39;est pas appairé à un autre téléphone ou à une autre application. Si vous utilisez le transmetteur avec une autre application, retirez-le de cette application ou désinstallez l&#39;application qui s&#39;y connecte. Si vous avez utilisé le transmetteur sur un autre téléphone, éteignez celui-ci maintenant ou supprimez l&#39;application qui se connectait à votre transmetteur.</li><li>Réinitialisez-le. Contactez le fabricant pour savoir comment faire.</li><li>Mettez-le en charge ou remplacez la pile.<br> Vous pouvez faire un scan Bluetooth avec l&#39;appareil en charge ; si vous ne pouvez vous y connecter que pendant la charge, la batterie interne est peut-être morte.</li></ol><p>Installez l&#39;application du fabricant pour écarter une panne de l&#39;appareil. Contactez le fabricant pour obtenir de l&#39;aide.</p><h3 id="bridge-doesnt-stay-connected" tabindex="-1">Le transmetteur ne reste pas connecté <a class="header-anchor" href="#bridge-doesnt-stay-connected" aria-label="Permalink to &quot;Le transmetteur ne reste pas connecté {#bridge-doesnt-stay-connected}&quot;">​</a></h3><p>Lorsque vous faites un scan Bluetooth, vous voyez et pouvez sélectionner votre transmetteur (il apparaît généralement en bleu comme appareil connu), mais il ne reste pas connecté : lors d&#39;un nouveau scan Bluetooth, il réapparaît.</p><h5 id="solution-1" tabindex="-1">Solution 1 : <a class="header-anchor" href="#solution-1" aria-label="Permalink to &quot;Solution 1 : {#solution-1}&quot;">​</a></h5><ol><li>État du système, Page d&#39;état classique -&gt; Oublier ce périphérique</li><li>Menu principal, Scan Bluetooth -&gt; Sélectionnez n&#39;importe quel appareil Bluetooth qui n&#39;est pas votre transmetteur</li><li>Attendez 10 secondes</li><li>État du système, Page d&#39;état classique -&gt; Oublier ce périphérique</li><li>Menu principal, Scan Bluetooth -&gt; Sélectionnez votre transmetteur</li></ol><h5 id="solution-2" tabindex="-1">Solution 2 : <a class="header-anchor" href="#solution-2" aria-label="Permalink to &quot;Solution 2 : {#solution-2}&quot;">​</a></h5><ol><li>État du système, Page d&#39;état classique -&gt; Oublier ce périphérique</li><li>Mettez le téléphone en mode avion</li><li>Attendez 10 secondes</li><li>Désactivez le mode avion</li><li>Désactivez le Bluetooth</li><li>Attendez 10 secondes</li><li>Activez le Bluetooth</li><li>Menu principal, Scan Bluetooth -&gt; Sélectionnez votre transmetteur</li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.03.27" target="_blank" rel="noreferrer"><em>Dernière modification le 28/3/2022</em></a></p>',56)])])}const P=c(h,[["render",v]]);export{x as __pageData,P as default};
